def solve(inputs: dict) -> float:
    base = None
    exp = None
    mod = None
    # Try common key names
    for k, v in inputs.items():
        kl = str(k).lower()
        if 'base' in kl:
            base = v
        elif 'exp' in kl or 'pow' in kl:
            exp = v
        elif 'mod' in kl:
            mod = v
    # Fallback: positional
    if base is None or exp is None or mod is None:
        vals = list(inputs.values())
        if len(vals) >= 3:
            base, exp, mod = vals[0], vals[1], vals[2]
    return float(pow(int(base), int(exp), int(mod)))

