def solve(inputs: dict) -> float:
    X = None
    a = None
    c = None
    m = None
    rounds = None
    for k, v in inputs.items():
        kl = str(k).lower()
        if 'start' in kl or 'begin' in kl or 'init' in kl or kl in ('x', 'x0', 'seed'):
            X = v
        elif 'round' in kl or 'iter' in kl or 'step' in kl or 'time' in kl:
            rounds = v
        elif 'mult' in kl or kl == 'a':
            a = v
        elif 'add' in kl or 'inc' in kl or kl == 'c':
            c = v
        elif 'mod' in kl or kl == 'm':
            m = v
    vals = list(inputs.values())
    # Fallback positional: start, a, c, m, rounds
    if X is None:
        X = vals[0]
    if a is None:
        a = vals[1]
    if c is None:
        c = vals[2]
    if m is None:
        m = vals[3]
    if rounds is None:
        rounds = vals[4]
    X = int(X); a = int(a); c = int(c); m = int(m); rounds = int(rounds)
    for _ in range(rounds):
        X = (a * X + c) % m
    return float(X)

