def solve(inputs: dict) -> float:
    n = None
    k = None
    for key, v in inputs.items():
        kl = str(key).lower()
        if 'people' in kl or 'people' in kl or kl == 'n' or 'count' in kl or 'position' in kl or 'circle' in kl:
            n = v
        elif kl == 'k' or 'th' in kl or 'every' in kl or 'step' in kl or 'skip' in kl:
            k = v
    vals = list(inputs.values())
    if n is None:
        n = vals[0]
    if k is None:
        k = vals[1]
    n = int(n); k = int(k)
    # Josephus, 1-indexed result
    res = 0
    for i in range(2, n + 1):
        res = (res + k) % i
    return float(res + 1)

